# 10-arapca-16 görsel modülü

GORSELLER = {'b1': "<svg viewBox='0 0 760 300' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='300' fill='#f8fafc' rx='12'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='bold' fill='#0f172a'>HOBİ SORMA: MÂ + İSİM / MÂZÂ + FİİL</text><rect x='20' y='48' width='340' height='190' rx='10' fill='#eff6ff' stroke='#2563eb' stroke-width='2'/><text x='190' y='72' text-anchor='middle' font-size='13' font-weight='bold' fill='#1d4ed8'>1. Mâ hivâyetuke? / Mâ hivâyetuki?</text><text x='190' y='92' text-anchor='middle' font-size='11' fill='#1e3a8a'>Hobin nedir? (erkeğe / kadına)</text><line x1='40' y1='104' x2='340' y2='104' stroke='#93c5fd'/><text x='190' y='124' text-anchor='middle' font-size='12' font-weight='bold' fill='#1e3a8a'>Cevap</text><text x='190' y='146' text-anchor='middle' font-size='12' fill='#1e3a8a'>Hivâyetî kuratu'l-kadem.</text><text x='190' y='166' text-anchor='middle' font-size='12' fill='#1e3a8a'>Hivâyetî kırâatu'l-kutub.</text><text x='190' y='190' text-anchor='middle' font-size='11' fill='#475569'>Hobim futbol. / Hobim kitap okumak.</text><text x='190' y='220' text-anchor='middle' font-size='10' fill='#475569'>Mâ hivâyetuhû? / Mâ hivâyetuhâ? : Onun hobisi ne?</text><circle cx='380' cy='143' r='16' fill='#0f172a'/><text x='380' y='148' text-anchor='middle' font-size='14' font-weight='bold' fill='#ffffff'>?</text><rect x='400' y='48' width='340' height='190' rx='10' fill='#fef3c7' stroke='#d97706' stroke-width='2'/><text x='570' y='72' text-anchor='middle' font-size='13' font-weight='bold' fill='#b45309'>2. Mâzâ tef'alu fî vakti farâğike?</text><text x='570' y='92' text-anchor='middle' font-size='11' fill='#78350f'>Boş vaktinde ne yaparsın? (erkeğe)</text><text x='570' y='110' text-anchor='middle' font-size='10' fill='#78350f'>Kadına: Mâzâ tef'alîne fî vakti farâğiki?</text><line x1='420' y1='118' x2='720' y2='118' stroke='#fcd34d'/><text x='570' y='138' text-anchor='middle' font-size='12' font-weight='bold' fill='#78350f'>Cevap</text><text x='570' y='160' text-anchor='middle' font-size='12' fill='#78350f'>Fî vakti farâğî el'abu'ş-şatranc.</text><text x='570' y='180' text-anchor='middle' font-size='12' fill='#78350f'>Ekdî vakte farâğî fi'r-resm.</text><text x='570' y='204' text-anchor='middle' font-size='11' fill='#475569'>Boş vaktimde satranç oynarım.</text><text x='570' y='222' text-anchor='middle' font-size='11' fill='#475569'>Boş vaktimi resim yaparak geçiririm.</text><rect x='20' y='252' width='720' height='36' rx='8' fill='#e2e8f0'/><text x='380' y='275' text-anchor='middle' font-size='12' font-weight='bold' fill='#1e293b'>hivâye + zamir: hivâyetî - hivâyetuke - hivâyetuki - hivâyetuhû - hivâyetuhâ (tâ merbûta açık tâ olur)</text></svg>", 'b2': "<svg viewBox='0 0 760 300' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='300' fill='#f8fafc' rx='12'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='bold' fill='#0f172a'>HOBİ FİİLLERİ VE ALDIKLARI HARF-İ CERLER</text><rect x='20' y='48' width='172' height='90' rx='10' fill='#eff6ff' stroke='#2563eb' stroke-width='2'/><text x='106' y='70' text-anchor='middle' font-size='13' font-weight='bold' fill='#1d4ed8'>umârisu</text><text x='106' y='88' text-anchor='middle' font-size='10' fill='#475569'>+ nesne (harf-i cer yok)</text><text x='106' y='108' text-anchor='middle' font-size='11' fill='#1e3a8a'>umârisu'r-riyâda</text><text x='106' y='126' text-anchor='middle' font-size='11' fill='#334155'>sporu yaparım</text><rect x='204' y='48' width='172' height='90' rx='10' fill='#fef2f2' stroke='#dc2626' stroke-width='2'/><text x='290' y='70' text-anchor='middle' font-size='13' font-weight='bold' fill='#b91c1c'>ehtemmu bi-</text><text x='290' y='88' text-anchor='middle' font-size='10' fill='#475569'>bi- + mecrur</text><text x='290' y='108' text-anchor='middle' font-size='11' fill='#7f1d1d'>ehtemmu bi'l-mesrah</text><text x='290' y='126' text-anchor='middle' font-size='11' fill='#334155'>tiyatroyla ilgilenirim</text><rect x='388' y='48' width='172' height='90' rx='10' fill='#f5f3ff' stroke='#7c3aed' stroke-width='2'/><text x='474' y='70' text-anchor='middle' font-size='13' font-weight='bold' fill='#6d28d9'>ekdî ... fî</text><text x='474' y='88' text-anchor='middle' font-size='10' fill='#475569'>vakit + fî + mastar</text><text x='474' y='108' text-anchor='middle' font-size='11' fill='#4c1d95'>ekdî vaktî fi'l-kırâa</text><text x='474' y='126' text-anchor='middle' font-size='11' fill='#334155'>vaktimi okuyarak geçiririm</text><rect x='572' y='48' width='172' height='90' rx='10' fill='#fff7ed' stroke='#ea580c' stroke-width='2'/><text x='658' y='70' text-anchor='middle' font-size='13' font-weight='bold' fill='#c2410c'>el'abu</text><text x='658' y='88' text-anchor='middle' font-size='10' fill='#475569'>+ oyun adı</text><text x='658' y='108' text-anchor='middle' font-size='11' fill='#7c2d12'>el'abu kurate's-selle</text><text x='658' y='126' text-anchor='middle' font-size='11' fill='#334155'>basketbol oynarım</text><rect x='20' y='148' width='172' height='90' rx='10' fill='#ecfdf5' stroke='#059669' stroke-width='2'/><text x='106' y='170' text-anchor='middle' font-size='13' font-weight='bold' fill='#047857'>uşâhidu</text><text x='106' y='188' text-anchor='middle' font-size='10' fill='#475569'>+ nesne</text><text x='106' y='208' text-anchor='middle' font-size='11' fill='#064e3b'>uşâhidu'l-mubârâh</text><text x='106' y='226' text-anchor='middle' font-size='11' fill='#334155'>maçı izlerim</text><rect x='204' y='148' width='172' height='90' rx='10' fill='#ecfeff' stroke='#0891b2' stroke-width='2'/><text x='290' y='170' text-anchor='middle' font-size='13' font-weight='bold' fill='#0e7490'>estemiu ilâ</text><text x='290' y='188' text-anchor='middle' font-size='10' fill='#475569'>ilâ + mecrur</text><text x='290' y='208' text-anchor='middle' font-size='11' fill='#164e63'>estemiu ile'l-enâşîd</text><text x='290' y='226' text-anchor='middle' font-size='11' fill='#334155'>neşideleri dinlerim</text><rect x='388' y='148' width='172' height='90' rx='10' fill='#fdf2f8' stroke='#db2777' stroke-width='2'/><text x='474' y='170' text-anchor='middle' font-size='13' font-weight='bold' fill='#be185d'>uhibbu</text><text x='474' y='188' text-anchor='middle' font-size='10' fill='#475569'>+ mastar / en + fiil</text><text x='474' y='208' text-anchor='middle' font-size='11' fill='#831843'>uhibbu'r-resm</text><text x='474' y='226' text-anchor='middle' font-size='11' fill='#334155'>resmi severim</text><rect x='572' y='148' width='172' height='90' rx='10' fill='#fefce8' stroke='#ca8a04' stroke-width='2'/><text x='658' y='170' text-anchor='middle' font-size='13' font-weight='bold' fill='#a16207'>ufaddılu ... alâ</text><text x='658' y='188' text-anchor='middle' font-size='10' fill='#475569'>nesne + alâ + mecrur</text><text x='658' y='208' text-anchor='middle' font-size='10' fill='#713f12'>ufaddılu's-sibâhate ale'l-cery</text><text x='658' y='226' text-anchor='middle' font-size='10' fill='#334155'>yüzmeyi koşuya tercih ederim</text><rect x='20' y='250' width='724' height='38' rx='8' fill='#e2e8f0'/><text x='382' y='274' text-anchor='middle' font-size='12' font-weight='bold' fill='#1e293b'>Ötreli ön ek: umârisu, uşâhidu, uhibbu, ufaddılu - Fethalı ön ek: ehtemmu, estemiu, ekdî, el'abu</text></svg>", 'b3': "<svg viewBox='0 0 760 300' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='300' fill='#f8fafc' rx='12'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='bold' fill='#0f172a'>TERCİH BİLDİRME: UFADDILU ... ALÂ ...</text><rect x='20' y='46' width='350' height='196' rx='10' fill='#ffffff' stroke='#cbd5e1' stroke-width='2'/><rect x='170' y='196' width='50' height='10' rx='3' fill='#64748b'/><line x1='195' y1='70' x2='195' y2='196' stroke='#64748b' stroke-width='4'/><line x1='95' y1='100' x2='295' y2='76' stroke='#334155' stroke-width='4'/><circle cx='195' cy='88' r='6' fill='#334155'/><line x1='95' y1='100' x2='70' y2='140' stroke='#94a3b8' stroke-width='2'/><line x1='95' y1='100' x2='120' y2='140' stroke='#94a3b8' stroke-width='2'/><ellipse cx='95' cy='142' rx='42' ry='9' fill='#2563eb'/><line x1='295' y1='76' x2='270' y2='114' stroke='#94a3b8' stroke-width='2'/><line x1='295' y1='76' x2='320' y2='114' stroke='#94a3b8' stroke-width='2'/><ellipse cx='295' cy='116' rx='42' ry='9' fill='#d97706'/><text x='95' y='170' text-anchor='middle' font-size='12' font-weight='bold' fill='#1d4ed8'>es-sibâhate</text><text x='95' y='186' text-anchor='middle' font-size='10' fill='#475569'>tercih edilen (mansub)</text><text x='295' y='144' text-anchor='middle' font-size='12' font-weight='bold' fill='#b45309'>ale'l-ceryi</text><text x='295' y='160' text-anchor='middle' font-size='10' fill='#475569'>alâ + mecrur</text><text x='195' y='224' text-anchor='middle' font-size='12' font-weight='bold' fill='#0f172a'>Ufaddılu's-sibâhate ale'l-cery.</text><text x='195' y='238' text-anchor='middle' font-size='10' fill='#475569'>Yüzmeyi koşuya tercih ederim.</text><rect x='390' y='46' width='350' height='60' rx='10' fill='#eff6ff' stroke='#2563eb' stroke-width='2'/><text x='565' y='68' text-anchor='middle' font-size='12' font-weight='bold' fill='#1d4ed8'>E-tufaddılu'r-resme emi'l-mûsîkâ?</text><text x='565' y='90' text-anchor='middle' font-size='11' fill='#1e3a8a'>Cevap: Ufaddılu'l-mûsîkâ. (evet / hayır yok)</text><rect x='390' y='114' width='350' height='60' rx='10' fill='#ecfdf5' stroke='#059669' stroke-width='2'/><text x='565' y='136' text-anchor='middle' font-size='12' font-weight='bold' fill='#047857'>Eyye riyâdatin tufaddılu?</text><text x='565' y='158' text-anchor='middle' font-size='11' fill='#064e3b'>Cevap: Ufaddılu kurate'l-kadem.</text><rect x='390' y='182' width='350' height='60' rx='10' fill='#fef3c7' stroke='#d97706' stroke-width='2'/><text x='565' y='204' text-anchor='middle' font-size='12' font-weight='bold' fill='#b45309'>Hel tufaddılu'ş-şatranc?</text><text x='565' y='226' text-anchor='middle' font-size='11' fill='#78350f'>Neam, ufaddıluhû. / Lâ, lâ ufaddıluhû.</text><rect x='20' y='254' width='720' height='34' rx='8' fill='#e2e8f0'/><text x='380' y='276' text-anchor='middle' font-size='12' font-weight='bold' fill='#1e293b'>Em sonrası el- gelirse emi okunur: emi'l-mûsîkâ - Eyye + tekil mecrur isim: eyye riyâdatin</text></svg>", 'b4': "<svg viewBox='0 0 760 320' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='320' fill='#f8fafc' rx='12'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='bold' fill='#0f172a'>SIKLIK ZARFLARI VE KEM MARRATEN SORUSU</text><rect x='20' y='46' width='460' height='220' rx='10' fill='#ffffff' stroke='#cbd5e1' stroke-width='2'/><line x1='40' y1='210' x2='465' y2='210' stroke='#334155' stroke-width='2'/><rect x='55' y='60' width='50' height='150' rx='4' fill='#1d4ed8'/><rect x='125' y='90' width='50' height='120' rx='4' fill='#2563eb'/><rect x='195' y='115' width='50' height='95' rx='4' fill='#3b82f6'/><rect x='265' y='155' width='50' height='55' rx='4' fill='#60a5fa'/><rect x='335' y='190' width='50' height='20' rx='4' fill='#93c5fd'/><rect x='405' y='207' width='50' height='3' rx='1' fill='#bfdbfe'/><text x='80' y='228' text-anchor='middle' font-size='11' font-weight='bold' fill='#0f172a'>dâimen</text><text x='80' y='244' text-anchor='middle' font-size='10' fill='#475569'>her zaman</text><text x='150' y='228' text-anchor='middle' font-size='11' font-weight='bold' fill='#0f172a'>ğâliben</text><text x='150' y='244' text-anchor='middle' font-size='10' fill='#475569'>çoğunlukla</text><text x='220' y='228' text-anchor='middle' font-size='11' font-weight='bold' fill='#0f172a'>âdeten</text><text x='220' y='244' text-anchor='middle' font-size='10' fill='#475569'>genellikle</text><text x='290' y='228' text-anchor='middle' font-size='11' font-weight='bold' fill='#0f172a'>ahyânen</text><text x='290' y='244' text-anchor='middle' font-size='10' fill='#475569'>bazen</text><text x='360' y='228' text-anchor='middle' font-size='11' font-weight='bold' fill='#0f172a'>nâdiren</text><text x='360' y='244' text-anchor='middle' font-size='10' fill='#475569'>nadiren</text><text x='430' y='228' text-anchor='middle' font-size='11' font-weight='bold' fill='#0f172a'>lâ ... ebeden</text><text x='430' y='244' text-anchor='middle' font-size='10' fill='#475569'>hiç</text><text x='250' y='258' text-anchor='middle' font-size='10' fill='#64748b'>Çubuklar sıklığın yaklaşık sırasını gösterir.</text><rect x='500' y='46' width='240' height='220' rx='10' fill='#fef3c7' stroke='#d97706' stroke-width='2'/><text x='620' y='70' text-anchor='middle' font-size='12' font-weight='bold' fill='#b45309'>Kem marraten ... fi'l-usbû'?</text><text x='620' y='88' text-anchor='middle' font-size='11' fill='#78350f'>Haftada kaç kez?</text><line x1='515' y1='98' x2='725' y2='98' stroke='#fcd34d'/><text x='620' y='120' text-anchor='middle' font-size='11' fill='#78350f'>marraten vâhideten : 1 kez</text><text x='620' y='142' text-anchor='middle' font-size='11' fill='#78350f'>marrateyn : 2 kez</text><text x='620' y='164' text-anchor='middle' font-size='11' fill='#78350f'>selâse marrât : 3 kez</text><text x='620' y='186' text-anchor='middle' font-size='11' fill='#78350f'>erbaa marrât : 4 kez</text><text x='620' y='208' text-anchor='middle' font-size='11' fill='#78350f'>kulle yevm : her gün</text><text x='620' y='232' text-anchor='middle' font-size='10' fill='#475569'>fi'ş-şehr : ayda</text><text x='620' y='250' text-anchor='middle' font-size='10' fill='#475569'>fî nihâyeti'l-usbû' : hafta sonu</text><rect x='20' y='276' width='720' height='34' rx='8' fill='#e2e8f0'/><text x='380' y='298' text-anchor='middle' font-size='12' font-weight='bold' fill='#1e293b'>Limâzâ? - Li-enne'r-riyâdate mufîdetun. (Neden? - Çünkü spor faydalıdır.)</text></svg>", 'b5': "<svg viewBox='0 0 760 300' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='300' fill='#f8fafc' rx='12'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='bold' fill='#0f172a'>GÖRÜŞ, YETENEK VE SOSYAL İFADE</text><rect x='20' y='46' width='350' height='168' rx='10' fill='#f5f3ff' stroke='#7c3aed' stroke-width='2'/><text x='195' y='70' text-anchor='middle' font-size='13' font-weight='bold' fill='#6d28d9'>GÖRÜŞ: Mâ ra'yuke fi'l-mesrah?</text><text x='195' y='88' text-anchor='middle' font-size='11' fill='#4c1d95'>Tiyatro hakkında ne düşünüyorsun?</text><text x='195' y='112' text-anchor='middle' font-size='12' fill='#4c1d95'>Fî ra'yî, el-mesrahu mumti'un.</text><text x='195' y='128' text-anchor='middle' font-size='10' fill='#475569'>Bence tiyatro zevklidir.</text><rect x='34' y='142' width='100' height='26' rx='13' fill='#ddd6fe'/><text x='84' y='159' text-anchor='middle' font-size='11' fill='#4c1d95'>mumti' : zevkli</text><rect x='145' y='142' width='100' height='26' rx='13' fill='#ddd6fe'/><text x='195' y='159' text-anchor='middle' font-size='11' fill='#4c1d95'>mufîd : faydalı</text><rect x='256' y='142' width='100' height='26' rx='13' fill='#ddd6fe'/><text x='306' y='159' text-anchor='middle' font-size='11' fill='#4c1d95'>mumill : sıkıcı</text><rect x='90' y='176' width='100' height='26' rx='13' fill='#ede9fe'/><text x='140' y='193' text-anchor='middle' font-size='11' fill='#4c1d95'>sehl : kolay</text><rect x='200' y='176' width='100' height='26' rx='13' fill='#ede9fe'/><text x='250' y='193' text-anchor='middle' font-size='11' fill='#4c1d95'>sa'b : zor</text><rect x='390' y='46' width='350' height='168' rx='10' fill='#ecfeff' stroke='#0891b2' stroke-width='2'/><text x='565' y='70' text-anchor='middle' font-size='13' font-weight='bold' fill='#0e7490'>YETENEK: Hel testatîu en tesbeha?</text><text x='565' y='88' text-anchor='middle' font-size='11' fill='#164e63'>Yüzebilir misin?</text><rect x='405' y='100' width='320' height='40' rx='8' fill='#d1fae5'/><text x='565' y='125' text-anchor='middle' font-size='12' fill='#065f46'>Neam, estatîu en esbeha. (Evet, yüzebilirim.)</text><rect x='405' y='148' width='320' height='40' rx='8' fill='#fee2e2'/><text x='565' y='173' text-anchor='middle' font-size='12' fill='#991b1b'>Lâ, lâ estatîu en esbeha. (Hayır, yüzemem.)</text><text x='565' y='206' text-anchor='middle' font-size='10' fill='#475569'>en + fethalı muzâri: en esbeha, en ersuma</text><rect x='60' y='228' width='280' height='40' rx='14' fill='#fef3c7' stroke='#d97706' stroke-width='2'/><polygon points='300,268 320,268 330,284' fill='#d97706'/><text x='200' y='253' text-anchor='middle' font-size='13' font-weight='bold' fill='#92400e'>Allâhu yu'tîke'l-âfiye!</text><rect x='420' y='228' width='280' height='40' rx='14' fill='#dcfce7' stroke='#16a34a' stroke-width='2'/><polygon points='440,268 460,268 430,284' fill='#16a34a'/><text x='560' y='253' text-anchor='middle' font-size='13' font-weight='bold' fill='#166534'>Allâhu yuâfîk.</text><text x='380' y='252' text-anchor='middle' font-size='18' fill='#334155'>→</text><text x='380' y='292' text-anchor='middle' font-size='11' fill='#475569'>Kolay gelsin, Allah sağlık versin. - Allah sana da afiyet versin.</text></svg>", 'b6': "<svg viewBox='0 0 760 300' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='300' fill='#f8fafc' rx='12'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='bold' fill='#0f172a'>OKUMA METNİ: ZEYNEB VE AHMED'İN HOBİLERİ</text><rect x='20' y='46' width='350' height='196' rx='10' fill='#eff6ff' stroke='#2563eb' stroke-width='2'/><text x='195' y='70' text-anchor='middle' font-size='14' font-weight='bold' fill='#1d4ed8'>ZEYNEB</text><text x='36' y='96' font-size='12' fill='#1e3a8a'>Hobi: kuratu's-selle (basketbol)</text><text x='36' y='120' font-size='12' fill='#1e3a8a'>Sıklık: selâse marrât fi'l-usbû'</text><text x='36' y='144' font-size='12' fill='#1e3a8a'>Tercih: ... ale's-sibâha (yüzmeye)</text><text x='36' y='168' font-size='12' fill='#1e3a8a'>Sebep: li-ennehâ cemâiyye ve mumtia</text><text x='36' y='192' font-size='12' fill='#1e3a8a'>İlgi: ehtemmu bi'l-mesrah</text><text x='36' y='216' font-size='12' fill='#1e3a8a'>Ahyânen: hafta sonu tiyatro izler</text><rect x='390' y='46' width='350' height='196' rx='10' fill='#ecfdf5' stroke='#059669' stroke-width='2'/><text x='565' y='70' text-anchor='middle' font-size='14' font-weight='bold' fill='#047857'>AHMED</text><text x='406' y='96' font-size='12' fill='#064e3b'>Boş vakit: kırâatu'l-kutub</text><text x='406' y='120' font-size='12' fill='#064e3b'>Âdeten: neşide dinler (yestemiu ilâ)</text><text x='406' y='144' font-size='12' fill='#064e3b'>Görüş: er-riyâdatu mufîde</text><text x='406' y='168' font-size='12' fill='#064e3b'>Yetenek: lâ estatîu en el'abe</text><text x='406' y='192' font-size='12' fill='#064e3b'>Davet: Teâle maî! (Benimle gel!)</text><text x='406' y='216' font-size='12' fill='#064e3b'>Şimdi: marraten fi'l-usbû' oynar</text><line x1='370' y1='144' x2='390' y2='144' stroke='#334155' stroke-width='3'/><rect x='20' y='252' width='720' height='38' rx='8' fill='#fef3c7' stroke='#d97706' stroke-width='1'/><text x='380' y='268' text-anchor='middle' font-size='12' font-weight='bold' fill='#92400e'>El-vikâyetu hayrun mine'l-ilâc : Korunmak tedaviden hayırlıdır.</text><text x='380' y='284' text-anchor='middle' font-size='11' fill='#78350f'>Antrenör: Allâhu yu'tîki'l-âfiye yâ Zeyneb! - Zeyneb: Allâhu yuâfîk.</text></svg>"}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
